  htt = `Intensitatea răspunsului haptic – Ridicată`,
  gtt = `Utilizează răspunsuri haptice de intensitate ridicată.`,
  _tt = `Clic`,
  vtt = `Comanda aceasta va fi realizată atunci când faci clic pe pad/stick.`,
  ytt = `Comanda înclinării la stânga`,
  btt = `Comanda aceasta va fi realizată atunci când înclini controlerul spre stânga.`,
  xtt = `Comanda înclinării la dreapta`,
  Stt = `Comanda aceasta va fi realizată atunci când înclini controlerul spre dreapta.`,
  Ctt = `Frecarea trackballului`,
  wtt = `Frecarea trackballului determină timpul de care are nevoie un trackball pentru a se opri atunci când se află în rotire liberă.`,
  Ttt = `Frecarea trackballului – Oprită`,
  Ett = `Dacă frecarea e dezactivată, trackballul nu va avea niciun impuls. Se va comporta ca și cum modul trackball este dezactivat.`,
  Dtt = `Frecarea trackballului – Redusă`,
  Ott = `La o frecare redusă, trackballul va continua să se rotească pentru o perioadă îndelungată după ce a fost mișcat, ajungând încet la momentul opririi.`,
  ktt = `Frecarea trackballului – Moderată`,
  Att = `La o frecare moderată, trackballul se va roti o perioadă după ce a fost mișcat și se va apropia treptat de momentul opririi.`,
  jtt = `Frecarea trackballului – Ridicată`,
  Mtt = `La o frecare ridicată, trackballul se va roti o perioadă după ce a fost mișcat și se va apropia rapid de momentul opririi.`,
  Ntt = `Frecarea trackballului – Fără`,
  Ptt = `Fără frecare, trackballul se va roti la nesfârșit după ce este mișcat, în lipsa unei intervenții exterioare.`,
  Ftt = `Scara de frecare verticală`,
  Itt = `Frecarea verticală determină cât de repede se oprește mișcarea verticală în raport cu mișcarea orizontală. Când glisorul se află la 50%, aceste viteze vor fi identice. Dacă valoarea este mai mică de 50%, mișcarea verticală va necesita mai mult timp pentru a se opri, iar dacă valoarea este mai mare de 50%, mișcarea verticală se va opri mai rapid. Pentru jocurile în care tu controlezi camera, se recomandă o frecare verticală mare pentru ca smucirile să fie folosite în principal pentru manevrarea camerei pe axa orizontală.`,
  Ltt = `Scara sensibilității verticale`,
  Rtt = `Scara sensibilității verticale determină cantitatea de mișcare verticală care are loc în raport cu mișcarea orizontală. Când glisorul se află la 50%, aceste valori sunt egale. În cazul în care glisorul se află sub 50%, mișcarea verticală va fi mai mică decât cea orizontală, în timp ce valori de peste 50% vor determina o mișcare verticală superioară celei orizontale.`,
